package com.safebox.self_storage.service;
import com.safebox.self_storage.dto.support.*; import com.safebox.self_storage.entity.*; import com.safebox.self_storage.exception.BusinessException; import com.safebox.self_storage.repository.*; import jakarta.persistence.*; import java.time.LocalDate; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class StaffScopeService {
 private final Sprint2Access access;private final UserRepository users;private final FacilityRepository facilities;private final UserFacilityAssignmentRepository assignments;private final SupportRequestRepository tickets;private final ActivityLogRepository logs;@PersistenceContext private EntityManager em;
 public StaffScopeService(Sprint2Access a,UserRepository u,FacilityRepository f,UserFacilityAssignmentRepository as,SupportRequestRepository t,ActivityLogRepository l){access=a;users=u;facilities=f;assignments=as;tickets=t;logs=l;}
 @Transactional(readOnly=true) public List<StaffScopeView> staff(){admin();return users.findAll().stream().filter(u->u.getRole()!=null&&"FACILITY_STAFF".equals(u.getRole().getRoleName())&&"ACTIVE".equals(u.getStatus())).map(this::view).toList();}
 @Transactional public StaffScopeView grant(UUID staffId,StaffFacilityAssignmentRequest x){admin();User s=staff(staffId);if(!facilities.existsById(x.facilityId()))throw new BusinessException(HttpStatus.NOT_FOUND,"Không tìm thấy cơ sở.");if(assignments.isUserAssignedToFacility(staffId,x.facilityId(),access.today()))return view(s);em.createNativeQuery("INSERT INTO USER_FACILITY_ASSIGNMENTS (assignment_id,user_id,facility_id,assigned_by,start_date,status) VALUES (NEWID(),:staff,:facility,:by,:today,'ACTIVE')").setParameter("staff",staffId).setParameter("facility",x.facilityId()).setParameter("by",access.currentId()).setParameter("today",access.today()).executeUpdate();logs.save(new ActivityLog(access.currentId(),"GRANT_STAFF_FACILITY","USER",staffId,"facilityId="+x.facilityId(),access.now()));return view(s);}
 @Transactional public StaffScopeView revoke(UUID staffId,UUID facilityId){admin();User s=staff(staffId);if(tickets.countOpenWork(staffId,facilityId,List.of("OPEN","IN_PROGRESS","RESOLVED"))>0)throw new BusinessException(HttpStatus.CONFLICT,"Nhân viên còn ticket đang mở tại cơ sở này. Hãy giao lại ticket trước.");int n=em.createNativeQuery("UPDATE USER_FACILITY_ASSIGNMENTS SET status='INACTIVE', end_date=:endDate WHERE user_id=:staff AND facility_id=:facility AND status='ACTIVE' AND start_date<=:today AND (end_date IS NULL OR end_date>=:today)").setParameter("staff",staffId).setParameter("facility",facilityId).setParameter("endDate",access.today().minusDays(1)).setParameter("today",access.today()).executeUpdate();if(n==0)throw new BusinessException(HttpStatus.NOT_FOUND,"Nhân viên không có phạm vi hoạt động tại cơ sở này.");logs.save(new ActivityLog(access.currentId(),"REVOKE_STAFF_FACILITY","USER",staffId,"facilityId="+facilityId,access.now()));return view(s);}
 private StaffScopeView view(User u){return new StaffScopeView(u.getUserId(),u.getFullName(),u.getEmail(),assignments.findActiveFacilityIds(u.getUserId(),access.today()).stream().map(id->facilities.findById(id).orElse(null)).filter(Objects::nonNull).map(f->new StaffScopeView.FacilityView(f.getFacilityId(),f.getName(),f.getAddress())).toList());} private User staff(UUID id){User u=users.findById(id).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Không tìm thấy nhân viên."));if(u.getRole()==null||!"FACILITY_STAFF".equals(u.getRole().getRoleName()))throw new BusinessException(HttpStatus.BAD_REQUEST,"Tài khoản không phải nhân viên cơ sở.");return u;}private void admin(){if(!"SYSTEM_ADMIN".equals(access.role()))throw new BusinessException(HttpStatus.FORBIDDEN,"Chỉ quản trị viên hệ thống được quản lý phạm vi nhân viên.");}}
